    if(type==='ending')return this.endingPanel();
    if(type==='illustration')return `<div class="illustration-viewer">${fullIllustration(id!,this.awakeningFor(id!))}<div><h2>${spiritById(id!).name}</h2><span>전신 일러스트</span><button class="outline-button" data-action="${this.view==='codex'?'close':'detail'}" data-id="${id}">${icon('back',14)} ${this.view==='codex'?'펼친 책으로':'요괴 정보'}</button></div></div>`;
