export const CAMPAIGN=CHAPTER_META.map((m,i)=>({...m,title:ROWS[i][0],boss:ROWS[i][1],arena:ROWS[i][2],intro:ROWS[i][3],outro:ROWS[i][4],jade:ROWS[i][5],theme:REGION_THEMES.findIndex(r=>r.name===m.region)}));
export const chapterInfo=(chapter:number)=>CAMPAIGN[Math.max(0,Math.min(19,chapter-1))];
export function stageName(chapter:number,stage:number){const c=chapterInfo(chapter),maps=REGION_THEMES[c.theme].maps;return stage===20?c.arena:`${maps[(stage-1)%maps.length]}${stage===10?' · 깊은 그림자':stage%5===0?' · 정예 습격':''}`;}
export const stageKey=(chapter:number,stage:number,difficulty:Difficulty)=>`${chapter}-${stage}-${DIFFICULTIES.indexOf(difficulty)}`;
export function regionStyle(chapter:number){const theme=chapterInfo(chapter).theme;return `--region-x:${theme%2*100}%;--region-y:${Math.floor(theme/2)*50}%;--region-color:${REGION_THEMES[theme].color}`;}
